-- Native homes use an independent authority and immutable versioned content.
ALTER TABLE tower_reception_cases ADD COLUMN home_mode TEXT NOT NULL DEFAULT 'external' CHECK(home_mode IN ('external','native'));
CREATE TABLE private_home_guards(ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE private_homes(id TEXT PRIMARY KEY CHECK(length(id)=16 AND id NOT GLOB '*[^0-9a-f]*'),case_id TEXT NOT NULL UNIQUE REFERENCES tower_reception_cases(id),revision INTEGER NOT NULL CHECK(revision>=1),public_revision INTEGER CHECK(public_revision IS NULL OR public_revision>=1),directory_consent INTEGER NOT NULL DEFAULT 0 CHECK(directory_consent IN (0,1)),dream_consent INTEGER NOT NULL DEFAULT 0 CHECK(dream_consent IN (0,1)),created_at TEXT NOT NULL);
CREATE TABLE private_home_snapshots(home_id TEXT NOT NULL REFERENCES private_homes(id),revision INTEGER NOT NULL,content_json TEXT NOT NULL CHECK(json_valid(content_json) AND length(CAST(content_json AS BLOB))<=65536),created_at TEXT NOT NULL,PRIMARY KEY(home_id,revision));
CREATE TABLE private_home_keys(hash TEXT PRIMARY KEY CHECK(length(hash)=64 AND hash NOT GLOB '*[^0-9a-f]*'),home_id TEXT NOT NULL REFERENCES private_homes(id),kind TEXT NOT NULL CHECK(kind IN ('owner','preview','session')),expires_at TEXT,revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN (0,1)),parent_hash TEXT REFERENCES private_home_keys(hash));
CREATE TABLE private_home_requests(home_id TEXT NOT NULL REFERENCES private_homes(id),request_key TEXT NOT NULL CHECK(length(request_key) BETWEEN 1 AND 100),input_hash TEXT NOT NULL CHECK(length(input_hash)=64 AND input_hash NOT GLOB '*[^0-9a-f]*'),response_json TEXT NOT NULL CHECK(json_valid(response_json)),status INTEGER NOT NULL CHECK(status IN (200,201)),PRIMARY KEY(home_id,request_key));
CREATE TABLE private_home_audit(id TEXT PRIMARY KEY,home_id TEXT NOT NULL REFERENCES private_homes(id),action TEXT NOT NULL,revision INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE private_home_assets(home_id TEXT NOT NULL,revision INTEGER NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('home','dream')),chunk INTEGER NOT NULL CHECK(chunk>=0),bytes BLOB NOT NULL CHECK(typeof(bytes)='blob' AND length(bytes) BETWEEN 1 AND 32768),PRIMARY KEY(home_id,revision,purpose,chunk),FOREIGN KEY(home_id,revision) REFERENCES private_home_snapshots(home_id,revision));
CREATE TRIGGER private_home_key_history AFTER INSERT ON private_home_keys BEGIN INSERT INTO identity_secret_history VALUES(NEW.hash);END;
CREATE TRIGGER private_home_case_mode BEFORE UPDATE OF home_mode ON tower_reception_cases WHEN NEW.home_mode IS NOT OLD.home_mode BEGIN SELECT RAISE(ABORT,'immutable_home_mode');END;
CREATE TRIGGER private_home_snapshots_update BEFORE UPDATE ON private_home_snapshots BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_snapshots_delete BEFORE DELETE ON private_home_snapshots BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_requests_update BEFORE UPDATE ON private_home_requests BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_requests_delete BEFORE DELETE ON private_home_requests BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_audit_update BEFORE UPDATE ON private_home_audit BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_audit_delete BEFORE DELETE ON private_home_audit BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_assets_update BEFORE UPDATE ON private_home_assets BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_assets_delete BEFORE DELETE ON private_home_assets BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
DROP TRIGGER admission_reception_insert;
CREATE TRIGGER admission_reception_insert BEFORE INSERT ON tower_reception_cases WHEN NEW.home_mode='external' AND (NEW.state IN ('approved','active')) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url AND (d.case_id=NEW.id OR (d.case_id IS NULL AND d.evidence_kind='existing-resident')))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
DROP TRIGGER admission_reception_update;
CREATE TRIGGER admission_reception_update BEFORE UPDATE ON tower_reception_cases WHEN NEW.home_mode='external' AND (NEW.state IN ('approved','active') AND (NEW.state!=OLD.state OR NEW.account_id IS NOT OLD.account_id OR NEW.resident_id IS NOT OLD.resident_id OR NEW.source_url IS NOT OLD.source_url OR NEW.approval_expires_at>OLD.approval_expires_at)) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url AND (d.case_id=NEW.id OR (d.case_id IS NULL AND d.evidence_kind='existing-resident')))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
DROP TRIGGER manager_move_in_case_insert;
CREATE TRIGGER manager_move_in_case_insert AFTER INSERT ON tower_reception_cases WHEN NEW.home_mode='external' AND NEW.request_kind='new' BEGIN INSERT INTO manager_move_in_progress(case_id,updated_at) VALUES(NEW.id,NEW.updated_at); END;
DROP TRIGGER manager_move_in_case_update;
CREATE TRIGGER manager_move_in_case_update AFTER UPDATE ON tower_reception_cases WHEN NEW.home_mode='external' AND NEW.request_kind='new' BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,version=version+1,updated_at=NEW.updated_at WHERE case_id=NEW.id; END;
-- Native case keys never mint imported-source authority.
CREATE TRIGGER private_home_case_binding_insert BEFORE INSERT ON tower_reception_cases WHEN NEW.home_mode='native' AND (NEW.state<>'active' OR NEW.is_muse_agent<>1 OR NEW.account_id IS NOT NULL OR NEW.source_url IS NOT NULL OR NEW.resident_id IS NOT NULL OR NEW.granted_token_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'native_case_binding');END;
CREATE TRIGGER private_home_case_binding_update BEFORE UPDATE ON tower_reception_cases WHEN OLD.home_mode='native' AND (NEW.account_id IS NOT NULL OR NEW.source_url IS NOT NULL OR NEW.resident_id IS NOT NULL OR NEW.granted_token_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'native_case_binding');END;
CREATE TABLE private_home_asset_metadata(home_id TEXT NOT NULL,revision INTEGER NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('home','dream')),sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),byte_length INTEGER NOT NULL CHECK(byte_length BETWEEN 1 AND 8388608),PRIMARY KEY(home_id,revision,purpose),FOREIGN KEY(home_id,revision) REFERENCES private_home_snapshots(home_id,revision));
CREATE TRIGGER private_home_asset_metadata_update BEFORE UPDATE ON private_home_asset_metadata BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_asset_metadata_delete BEFORE DELETE ON private_home_asset_metadata BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_namespace_accounts BEFORE INSERT ON accounts WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.login_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_sessions BEFORE INSERT ON sessions WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_tower_tokens BEFORE INSERT ON tower_tokens WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_agent_tokens BEFORE INSERT ON agent_tokens WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_onboarding_grants BEFORE INSERT ON onboarding_grants WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_tower_reception_cases BEFORE INSERT ON tower_reception_cases WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_account_update BEFORE UPDATE OF login_hash ON accounts WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.login_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
-- Text/key/publication revisions reference immutable artwork instead of copying blobs.
CREATE TABLE private_home_asset_refs(home_id TEXT NOT NULL,revision INTEGER NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('home','dream')),asset_revision INTEGER NOT NULL CHECK(asset_revision>=1),PRIMARY KEY(home_id,revision,purpose),FOREIGN KEY(home_id,revision) REFERENCES private_home_snapshots(home_id,revision),FOREIGN KEY(home_id,asset_revision,purpose) REFERENCES private_home_asset_metadata(home_id,revision,purpose));
CREATE TRIGGER private_home_asset_refs_update BEFORE UPDATE ON private_home_asset_refs BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_asset_refs_delete BEFORE DELETE ON private_home_asset_refs BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_case_revoked AFTER UPDATE OF state ON tower_reception_cases WHEN OLD.home_mode='native' AND NEW.state IN ('revoked','rejected','withdrawn') BEGIN
 UPDATE private_home_keys SET revoked=1 WHERE home_id IN (SELECT id FROM private_homes WHERE case_id=NEW.id);
 UPDATE private_homes SET public_revision=NULL,directory_consent=0,dream_consent=0 WHERE case_id=NEW.id;
 INSERT INTO private_home_audit SELECT lower(hex(randomblob(16))),id,'case-revoked',revision,NEW.updated_at FROM private_homes WHERE case_id=NEW.id;
END;
CREATE TRIGGER private_home_namespace_update_sessions BEFORE UPDATE OF token_hash ON sessions WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_update_tower_tokens BEFORE UPDATE OF token_hash ON tower_tokens WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_update_agent_tokens BEFORE UPDATE OF token_hash ON agent_tokens WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_update_onboarding_grants BEFORE UPDATE OF token_hash ON onboarding_grants WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_namespace_update_tower_reception_cases BEFORE UPDATE OF token_hash ON tower_reception_cases WHEN EXISTS(SELECT 1 FROM private_home_keys WHERE hash=NEW.token_hash) BEGIN SELECT RAISE(ABORT,'private_home_key_namespace');END;
CREATE TRIGGER private_home_snapshot_shape BEFORE INSERT ON private_home_snapshots BEGIN
 SELECT CASE WHEN json_valid(NEW.content_json) AND json_type(NEW.content_json)='object' AND (SELECT count(*) FROM json_each(NEW.content_json))=5 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.content_json) WHERE key NOT IN ('name','intro','profile','journal','dream') OR type<>'text') AND length(json_extract(NEW.content_json,'$.name')) BETWEEN 1 AND 80 AND length(json_extract(NEW.content_json,'$.intro'))<=1200 AND length(json_extract(NEW.content_json,'$.profile'))<=16000 AND length(json_extract(NEW.content_json,'$.journal'))<=16000 AND length(json_extract(NEW.content_json,'$.dream'))<=16000 THEN 1 ELSE RAISE(ABORT,'native_content_shape') END;
END;
CREATE TRIGGER private_home_key_binding BEFORE INSERT ON private_home_keys BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM identity_secret_history WHERE secret_hash=NEW.hash) AND NEW.revoked=0 AND ((NEW.kind='owner' AND NEW.expires_at IS NULL AND NEW.parent_hash IS NULL) OR (NEW.kind='preview' AND NEW.expires_at IS NOT NULL AND NEW.parent_hash IS NULL) OR (NEW.kind='session' AND NEW.expires_at IS NOT NULL AND EXISTS(SELECT 1 FROM private_home_keys p WHERE p.hash=NEW.parent_hash AND p.home_id=NEW.home_id AND p.kind='preview' AND p.revoked=0 AND p.expires_at>=NEW.expires_at))) THEN 1 ELSE RAISE(ABORT,'native_key_binding') END;
END;
CREATE TRIGGER private_home_key_immutable BEFORE UPDATE ON private_home_keys WHEN NEW.hash IS NOT OLD.hash OR NEW.home_id IS NOT OLD.home_id OR NEW.kind IS NOT OLD.kind OR NEW.expires_at IS NOT OLD.expires_at OR NEW.parent_hash IS NOT OLD.parent_hash OR NEW.revoked<OLD.revoked BEGIN SELECT RAISE(ABORT,'immutable_native_key');END;
CREATE TRIGGER private_home_key_permanent BEFORE DELETE ON private_home_keys BEGIN SELECT RAISE(ABORT,'permanent_native_key');END;
CREATE TRIGGER private_home_snapshots_replace_guard BEFORE INSERT ON private_home_snapshots WHEN EXISTS(SELECT 1 FROM private_home_snapshots WHERE home_id=NEW.home_id AND revision=NEW.revision) BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_requests_replace_guard BEFORE INSERT ON private_home_requests WHEN EXISTS(SELECT 1 FROM private_home_requests WHERE home_id=NEW.home_id AND request_key=NEW.request_key) BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_audit_replace_guard BEFORE INSERT ON private_home_audit WHEN EXISTS(SELECT 1 FROM private_home_audit WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_assets_replace_guard BEFORE INSERT ON private_home_assets WHEN EXISTS(SELECT 1 FROM private_home_assets WHERE home_id=NEW.home_id AND revision=NEW.revision AND purpose=NEW.purpose AND chunk=NEW.chunk) BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_asset_metadata_replace_guard BEFORE INSERT ON private_home_asset_metadata WHEN EXISTS(SELECT 1 FROM private_home_asset_metadata WHERE home_id=NEW.home_id AND revision=NEW.revision AND purpose=NEW.purpose) BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE TRIGGER private_home_asset_refs_replace_guard BEFORE INSERT ON private_home_asset_refs WHEN EXISTS(SELECT 1 FROM private_home_asset_refs WHERE home_id=NEW.home_id AND revision=NEW.revision AND purpose=NEW.purpose) BEGIN SELECT RAISE(ABORT,'immutable_private_home_record');END;
CREATE UNIQUE INDEX private_home_owner_active ON private_home_keys(home_id) WHERE kind='owner' AND revoked=0;
